css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; display: grid; place-items: center; perspective: 260px; }
.loader span { position: absolute; width: 60%; height: 60%; border: calc(var(--loader-size) * .028) solid var(--accent); border-radius: 50%; opacity: 0; animation: pool calc(var(--loader-speed) * 2.4) ease-out infinite; }
.loader span:nth-child(2) { border-color: var(--accent-2); animation-delay: calc(var(--loader-speed) * .8); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * 1.6); }
@keyframes pool { 0% { transform: rotateX(62deg) scale(.15); opacity: 1; } 100% { transform: rotateX(62deg) scale(1.5); opacity: 0; } }
